// Writes core/build/engine.js from core/app/engine.js; --check fails when the
// committed bundle is stale, the way gen-tokens.mjs does for tokens.css.
//
// A shell whose JavaScript engine has no module loader (JavaScriptCore on iOS,
// Android's embedded engine) cannot import core's files, and a hand-written
// Swift or Kotlin copy of a rule is exactly what this project refuses. So the
// bundle is built here, committed, and held fresh by a test.
import { build } from 'esbuild';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const ENTRY = path.join(root, 'core/app/engine.js');
export const OUT = path.join(root, 'core/build/engine.js');
export const BANNER = '// Generated by scripts/gen-engine-bundle.mjs from core/app/engine.js; do not edit.';

/** The bundle a shell is given: one script that defines the global `engine`. */
export async function bundleEngine() {
  const result = await build({
    entryPoints: [ENTRY],
    bundle: true,
    format: 'iife',
    // ★ The global carries no product name: naming.json owns the name, and code
    // never carries one.
    globalName: 'engine',
    platform: 'neutral',
    target: 'es2020',
    legalComments: 'none',
    banner: { js: BANNER },
    write: false,
  });
  return result.outputFiles[0].text;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const code = await bundleEngine();
  if (process.argv.includes('--check')) {
    let current = null;
    try {
      current = readFileSync(OUT, 'utf8');
    } catch {
      console.error('core/build/engine.js is missing: run pnpm run engine');
      process.exit(1);
    }
    if (current !== code) {
      console.error('core/build/engine.js is stale: run pnpm run engine');
      process.exit(1);
    }
    console.log('core/build/engine.js is fresh');
  } else {
    mkdirSync(path.dirname(OUT), { recursive: true });
    writeFileSync(OUT, code);
    console.log('wrote core/build/engine.js');
  }
}
